import json
import re
import sys
import os

def parse_script(text: str):
    nodes = []
    edges = []

    lines = text.splitlines()

    current_node_id = None
    current_block_lines = []

    # Helper to process a finished block
    def process_block(node_id, block_lines):
        if not node_id:
            return

        parsed_edges = []
        node_speaker = ""
        node_text = ""
        node_type = "choice" 

        edges_in_block = []

        is_dialogue_candidate = (len(block_lines) == 1)

        for line in block_lines:
            if "->" not in line:
                print(f"Warning: Line in block {node_id} has no '->': {line}", file=sys.stderr)
                continue

            parts = line.split("->")
            # Assume last -> separates target
            target = parts[-1].strip()
            content = "->".join(parts[:-1]).strip()

            edges_in_block.append({"content": content, "target": target})

        if not edges_in_block:
            return

        # Determine type
        if is_dialogue_candidate:
            content = edges_in_block[0]["content"]
            # Look for the FIRST colon.
            if ": " in content:
                split_content = content.split(": ", 1)
                speaker = split_content[0].strip()
                # Heuristic: If speaker starts with digit, it is likely a choice enumeration
                if re.match(r'^\d+\.', speaker):
                     node_type = "choice"
                else:
                    node_type = "line"
                    node_speaker = speaker
                    node_text = split_content[1].strip()
            else:
                node_type = "choice"
        else:
            node_type = "choice"

        # Create Node
        nodes.append({
            "id": node_id,
            "text": node_text,
            "speaker": node_speaker,
            "type": node_type
        })

        # Create Edges
        for edge_info in edges_in_block:
            edge_text = edge_info["content"]
            if node_type == "line":
                edge_text_final = ""
            else:
                edge_text_final = edge_text

            edges.append({
                "from": node_id,
                "to": edge_info["target"],
                "text": edge_text_final
            })

    for line in lines:
        line = line.strip()
        if not line:
            continue

        # Check for section header
        if line.startswith("[") and line.endswith("]"):
            # Process previous block
            if current_node_id:
                process_block(current_node_id, current_block_lines)

            current_node_id = line[1:-1].strip()
            current_block_lines = []
        else:
            # Add line to current block
            if current_node_id:
                current_block_lines.append(line)

    # Process last block
    if current_node_id:
        process_block(current_node_id, current_block_lines)

    # Post-processing: Check for implicit "End" node
    existing_ids = set(n["id"] for n in nodes)
    referenced_targets = set(e["to"] for e in edges)

    for target in referenced_targets:
        if target not in existing_ids:
            if target == "End":
                nodes.append({
                    "id": "End",
                    "text": "",
                    "speaker": "",
                    "type": "line"
                })
                existing_ids.add("End")
            else:
                nodes.append({
                    "id": target,
                    "text": "Placeholder",
                    "speaker": "System",
                    "type": "line"
                })
                existing_ids.add(target)

    return {"nodes": nodes, "edges": edges}

def generate_dot(graph):
    dot_lines = []
    dot_lines.append("digraph Dialogue {")
    dot_lines.append("  node [shape=box, fontname=\"Arial\"];")
    dot_lines.append("  edge [fontname=\"Arial\", fontsize=10];")

    # Nodes
    for node in graph["nodes"]:
        label = node["id"]
        if node["type"] == "line" and node["speaker"]:
            text = node["text"].replace('"', '\\"')
            label = f"{node['speaker']}: {text}"
            if len(label) > 50:
                label = label[:47] + "..."
        elif node["type"] == "choice":
            label = f"[{node['id']}]"

        dot_lines.append(f"  \"{node['id']}\" [label=\"{label}\"];")

    # Edges
    for edge in graph["edges"]:
        label = edge["text"]
        label = label.replace('"', '\\"')
        if len(label) > 30:
            label = label[:27] + "..."

        dot_lines.append(f"  \"{edge['from']}\" -> \"{edge['to']}\" [label=\"{label}\"];")

    dot_lines.append("}")
    return "\n".join(dot_lines)

if __name__ == "__main__":
    input_path = "/app/script.txt"
    json_path = "/app/dialogue.json"
    dot_path = "/app/dialogue.dot"

    if not os.path.exists(input_path):
        print(f"Error: {input_path} not found.")
        sys.exit(1)

    with open(input_path, "r", encoding="utf-8") as f:
        text = f.read()

    graph = parse_script(text)

    with open(json_path, "w", encoding="utf-8") as f:
        json.dump(graph, f, indent=2)

    dot_content = generate_dot(graph)
    with open(dot_path, "w", encoding="utf-8") as f:
        f.write(dot_content)

    print(f"Generated {json_path} and {dot_path}")

